function animateMetric(el,value,format){const from=Number(el.dataset.value)||0,to=Number(value)||0,start=performance.now(),duration=600;el.dataset.value=to;function frame(now){const progress=Math.min(1,(now-start)/duration),eased=1-Math.pow(1-progress,4);el.textContent=format(from+(to-from)*eased);if(progress<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}
function clock(){const d=new Date(),minuteKey=Math.floor(d.getTime()/60000),minuteChanged=lastClockMinute!==null&&lastClockMinute!==minuteKey;lastClockMinute=minuteKey;$('#clock').textContent=d.toLocaleTimeString('ru-RU');$('#todayDate').textContent=d.toLocaleDateString('ru-RU',{day:'numeric',month:'long'});$('#todayDay').textContent=d.toLocaleDateString('ru-RU',{weekday:'long'});if(minuteChanged){renderSchedule();renderRooms();return}const now=d.getHours()*60+d.getMinutes()+d.getSeconds()/60;const firstStart=clockMinutes(periods[0].start);let status='Занятия завершены на сегодня.';if(d.getDay()!==0){if(now<firstStart){status=`Занятия ещё не начались. До звонка на 1 пару осталось: ${minutesUntil(periods[0].start,now)} мин.`}else if(now<clockMinutes(periods[periods.length-1].end)){for(const period of periods){const start=clockMinutes(period.start),firstEnd=clockMinutes(period.firstEnd),breakEnd=clockMinutes(period.breakEnd),end=clockMinutes(period.end);if(now>=start&&now<firstEnd){status=`Сейчас идёт ${period.number} пара. До пятиминутки осталось: ${minutesUntil(period.breakStart,now)} мин.`;break}if(now>=firstEnd&&now<breakEnd){status=`Сейчас пятиминутка внутри ${period.number} пары. До звонка на 2 часть: ${minutesUntil(period.breakEnd,now)} мин.`;break}if(now>=breakEnd&&now<end){status=`Сейчас идёт ${period.number} пара. До звонка осталось: ${minutesUntil(period.end,now)} мин.`;break}if(period.next&&now>=end&&now<clockMinutes(period.next)){status=`Сейчас перемена. До звонка на ${period.number+1} пару осталось: ${minutesUntil(period.next,now)} мин.`;break}}}}$('#lessonStatus').textContent=status;}
function renderDays(){const todayIndex=new Date().getDay()-1;$('#dayTabs').innerHTML=days.map((d,i)=>`<button class="${i===selectedDay?'active':''}" data-day="${i}">${d}${i===todayIndex?' <span class="today-marker" title="Сегодня">●</span>':''}</button>`).join('');$$('#dayTabs button').forEach(b=>b.onclick=()=>{selectedDay=+b.dataset.day;renderSchedule()})}
