function renderSchedule(){renderDays();updateTomorrowButton();const g=$('#groupSelect').value,items=(schedule[g]&&schedule[g][days[selectedDay]])||[],todayIndex=new Date().getDay()-1,now=new Date(),nowMinutes=now.getHours()*60+now.getMinutes()+now.getSeconds()/60;$('#scheduleGrid').innerHTML=items.length?items.map((x,i)=>{const p=periods[i%periods.length],isCurrent=selectedDay===todayIndex&&nowMinutes>=clockMinutes(p.start)&&nowMinutes<clockMinutes(p.end)&&x[0]!=='—',room=escapeHtml(x[2]);return `<article class="schedule-card ${x[0]==='—'?'empty ':''}${isCurrent?'is-current':''}"><span class="lesson-num">${i+1} ПАРА · ${p.start}–${p.end}${isCurrent?' <b class="now-badge">● СЕЙЧАС</b>':''}</span><h3>${escapeHtml(x[0])}</h3><p>◉ ${escapeHtml(x[1])}</p><p>⌖ <button class="room-link" type="button" data-room="${room}">Кабинет ${room}</button></p><small>${p.start}–${p.end} (перерыв ${p.breakStart}–${p.breakEnd})</small></article>`}).join(''):'<div class="card empty-state">Расписание на этот день в присланных листах не указано.</div>';$$('.room-link').forEach(button=>button.onclick=()=>focusRoom(button.dataset.room));clock();}
function normalizeSearch(value){return String(value||'').toLocaleLowerCase('ru-RU').trim().replace(/[^\p{L}\p{N}]+/gu,' ').replace(/\s+/g,' ').trim()}
function searchTokens(value){const normalized=normalizeSearch(value);return normalized?normalized.split(' '):[]}
function getRoomScheduleText(roomNumber){const target=normalizeSearch(roomNumber),values=[];Object.values(schedule).forEach(groupDays=>Object.values(groupDays||{}).forEach(lessons=>(lessons||[]).forEach(lesson=>{if(normalizeSearch(lesson[2])===target)values.push(`${lesson[0]} ${lesson[1]}`)})));return values.join(' ')}
function getRoomLiveStatus(roomNumber){const now=new Date(),dayIndex=now.getDay()-1;if(dayIndex<0||dayIndex>=days.length)return null;const nowMinutes=now.getHours()*60+now.getMinutes()+now.getSeconds()/60;const period=periods.find(item=>nowMinutes>=clockMinutes(item.start)&&nowMinutes<clockMinutes(item.end));if(!period)return{occupied:false};const day=days[dayIndex],target=normalizeSearch(roomNumber);for(const [group,groupDays] of Object.entries(schedule)){const lesson=(groupDays[day]||[])[period.number-1];if(lesson&&normalizeSearch(lesson[2])===target&&lesson[0]&&lesson[0]!=='—')return{occupied:true,lesson:lesson[0],group,teacher:lesson[1],periodNum:period.number}}return{occupied:false}}
function renderRooms(){const query=normalizeSearch($('#roomSearch').value),queryTokens=searchTokens(query),building=$('#buildingFilter').value;const exactCode=query?rooms.filter(room=>normalizeSearch(room[0])===query):[];const found=rooms.filter(room=>{if(building&&room[1]!==building)return false;if(!query)return true;if(exactCode.length)return exactCode.includes(room);const codeTokens=searchTokens(room[0]);if(queryTokens.length===1&&codeTokens.some(token=>token.startsWith(queryTokens[0])))return true;const fields=[room[1],room[2],room[3],room[4],getRoomScheduleText(room[0])];const fieldTokens=fields.flatMap(searchTokens);return queryTokens.every(token=>fieldTokens.some(fieldToken=>fieldToken===token||fieldToken.startsWith(token)))});$('#roomResults').innerHTML=found.length?found.map(room=>{const status=getRoomLiveStatus(room[0]),live=status&&status.occupied;const banner=live?`<div class="room-live-banner occupied"><span class="live-dot pulse">●</span><div><b>Сейчас идёт ${status.periodNum} пара:</b> ${escapeHtml(status.lesson)} · гр. ${escapeHtml(status.group)} (${escapeHtml(status.teacher)})</div></div>`:status?'<div class="room-live-banner free"><span class="live-dot">●</span><div>Сейчас занятий нет</div></div>':'';return `<article class="room-card ${live?'is-occupied':''}"><span class="room-tag">${escapeHtml(room[1])}</span><h3>Кабинет ${escapeHtml(room[0])}</h3><p><b>${escapeHtml(room[2])}</b></p><p>Преподаватель: ${escapeHtml(room[3])}</p><p>⌖ ${escapeHtml(room[4])}</p>${banner}</article>`}).join(''):'<div class="card">Ничего не найдено. Измените запрос.</div>';}
const methodologyData=[
 {id:'bep',category:'economy',categoryLabel:'Экономика и налоги',title:'Точка безубыточности (CVP / BEP)',formula:'BEP = FC / (P − AVC)',variables:'FC — постоянные затраты, ₽; P — цена единицы, ₽; AVC — переменные затраты на единицу, ₽; BEP — критический объем, шт.',derivation:'В точке безубыточности прибыль равна нулю, поэтому выручка равна совокупным затратам: TR = TC. Подставляя TR = P × Q и TC = FC + AVC × Q, получаем P × Q = FC + AVC × Q. После переноса переменной части: Q × (P − AVC) = FC. Отсюда BEP = FC / (P − AVC).',example:'При FC = 85 000 ₽, P = 1 200 ₽ и AVC = 650 ₽: BEP = 85 000 / 550 = 154,5, то есть необходимо реализовать минимум 155 единиц продукции.',keywords:'CVP выручка затраты порог рентабельности точка безубыточности',chart:'bep'},
 {id:'safety',category:'economy',categoryLabel:'Экономика и налоги',title:'Запас финансовой прочности',formula:'FS = ((Q − BEP) / Q) × 100%',variables:'Q — плановый объем продаж, шт.; BEP — точка безубыточности, шт.; FS — запас финансовой прочности, %.',derivation:'Запас прочности показывает, на какую долю может сократиться объем продаж до достижения критической точки. Разность Q − BEP отражает допустимое снижение продаж. Деление на фактический объем Q переводит показатель в относительную форму, а умножение на 100% — в проценты.',example:'При Q = 300 шт. и BEP = 155 шт. FS = ((300 − 155) / 300) × 100% = 48,3%. Это означает, что продажи могут снизиться примерно на 48% до перехода в зону убытка.',keywords:'финансовая прочность риск запас продаж',chart:null},
 {id:'depreciation',category:'economy',categoryLabel:'Экономика и налоги',title:'Линейная амортизация основных средств',formula:'Aгод = (Sперв − Sликв) / T;  Aмес = Aгод / 12',variables:'Sперв — первоначальная стоимость, ₽; Sликв — ликвидационная стоимость, ₽; T — срок полезного использования, лет; A — амортизация.',derivation:'При линейном методе амортизируемая стоимость распределяется равными долями в течение всего срока эксплуатации. Амортизируемая стоимость равна Sперв − Sликв. Деление на T дает годовую сумму, а деление результата на 12 — ежемесячную сумму.',example:'Для оборудования стоимостью 1 200 000 ₽, ликвидационной стоимостью 120 000 ₽ и СПИ 5 лет: Aгод = 216 000 ₽, Aмес = 18 000 ₽. После первого года остаточная стоимость составит 984 000 ₽.',keywords:'амортизация основные средства СПИ остаточная стоимость',chart:'depreciation'},
 {id:'annuity',category:'economy',categoryLabel:'Экономика и налоги',title:'Аннуитетный платёж по кредиту',formula:'A = S × [i(1+i)ⁿ] / [(1+i)ⁿ − 1]',variables:'S — сумма кредита, ₽; i — месячная процентная ставка; n — количество платежей; A — фиксированный ежемесячный платеж.',derivation:'Аннуитет — финансовая рента с равными платежами. Текущая стоимость платежей равна сумме дисконтированных платежей: S = A × [1 − (1+i)⁻ⁿ] / i. Выражая A из равенства, получаем формулу аннуитетного платежа.',example:'Для кредита 500 000 ₽ на 24 месяца под 18% годовых месячная ставка равна 0,015. Ежемесячный платеж составляет примерно 24 962 ₽, а общая сумма выплат — около 599 088 ₽.',keywords:'кредит финансовая рента проценты платеж',chart:'annuity'},
 {id:'usn',category:'economy',categoryLabel:'Экономика и налоги',title:'Налоговый вычет УСН «Доходы» 6%',formula:'Налог к уплате = max(0, Налог начисленный − Вычет)',variables:'Налог начисленный = Доход × 6%; вычет — страховые взносы и иные разрешенные суммы; при наличии сотрудников вычет ограничен 50% начисленного налога.',derivation:'Сначала определяется налоговая база в виде всей выручки, затем применяется ставка 6%. Статья 346.21 НК РФ разрешает уменьшить налог на страховые взносы. Если у организации есть работники, сумма уменьшения не может превышать половину начисленного налога.',example:'При доходе 600 000 ₽ налог равен 36 000 ₽. При взносах 50 000 ₽ и наличии сотрудников максимальный вычет равен 18 000 ₽, поэтому к уплате остается 18 000 ₽.',keywords:'УСН 6% налоговый вычет 346.21 взносы',chart:null},
 {id:'cutting',category:'technology',categoryLabel:'Технология и обработка',title:'Скорость резания при точении',formula:'v = (π × D × n) / 1000',variables:'D — диаметр заготовки, мм; n — частота вращения шпинделя, об/мин; v — скорость резания, м/мин.',derivation:'За один оборот точка на поверхности проходит длину окружности L = πD. За минуту при n оборотах путь равен πDn миллиметров. Перевод из миллиметров в метры выполняется делением на 1000, поэтому v = πDn / 1000.',example:'При D = 80 мм и n = 500 об/мин: v = 3,1416 × 80 × 500 / 1000 = 125,7 м/мин. Для стали это рабочая скорость средней величины.',keywords:'точение резание станок диаметр шпиндель технология',chart:'cutting'},
 {id:'threephase',category:'electrical',categoryLabel:'Электротехника',title:'Электрическая мощность трёхфазной сети',formula:'P = √3 × Uлин × Iлин × cosφ',variables:'Uлин — линейное напряжение, В; Iлин — линейный ток, А; cosφ — коэффициент мощности; P — активная мощность, Вт.',derivation:'Для симметричной трехфазной системы P = 3 × Uф × Iф × cosφ. При соединении звездой Uлин = √3 × Uф, а Iлин = Iф. Подстановка этих соотношений дает P = √3 × Uлин × Iлин × cosφ.',example:'Станок при Uлин = 380 В, Iлин = 12 А и cosφ = 0,82 потребляет P = 1,732 × 380 × 12 × 0,82 ≈ 6,48 кВт.',keywords:'электротехника мощность трехфазная сеть станок cos phi',chart:null},
 {id:'mass',category:'technology',categoryLabel:'Технология и обработка',title:'Плотность и масса заготовок',formula:'m = ρ × V;  Vцилиндра = πr²L',variables:'m — масса, кг; ρ — плотность материала, кг/м³; V — объем, м³; r — радиус, м; L — длина, м.',derivation:'Плотность определяется как отношение массы к объему: ρ = m / V. Умножением обеих частей на V получаем m = ρV. Для цилиндрического прутка объем равен площади основания πr², умноженной на длину L.',example:'Стальной пруток диаметром 50 мм и длиной 2 м имеет объем π × 0,025² × 2 ≈ 0,003927 м³. При плотности стали 7 850 кг/м³ масса составляет примерно 30,8 кг.',keywords:'плотность масса сталь пруток цилиндр объем',chart:null}
];
let methodologyChart=null;
let methodologyCategory='all';
function renderMethodology(){const query=normalizeSearch($('#methodologySearch')?.value||''),tokens=searchTokens(query),grid=$('#methodologyGrid');if(!grid)return;const found=methodologyData.filter(item=>(methodologyCategory==='all'||item.category===methodologyCategory)&&(!tokens.length||tokens.every(token=>searchTokens(`${item.title} ${item.formula} ${item.categoryLabel} ${item.variables} ${item.derivation} ${item.example} ${item.keywords}`).some(value=>value.includes(token)))));grid.innerHTML=found.length?found.map(item=>`<article class="card method-card"><span class="method-category">${escapeHtml(item.categoryLabel)}</span><h2>${escapeHtml(item.title)}</h2><div class="method-card-formula">${escapeHtml(item.formula)}</div><p>${escapeHtml(item.example)}</p><button class="method-details-btn" type="button" data-methodology-id="${item.id}">Подробнее с выводом и графиком →</button></article>`).join(''):'<div class="card empty-state">По вашему запросу формулы не найдены.</div>';$$('[data-methodology-id]').forEach(button=>button.onclick=()=>openMethodologyModal(button.dataset.methodologyId))}
function openMethodologyModal(id){const item=methodologyData.find(value=>value.id===id);if(!item)return;$('#methodologyModalTitle').textContent=item.title;$('#methodologyModalCategory').textContent=item.categoryLabel;$('#methodologyFormula').textContent=item.formula;$('#methodologyVariables').textContent=item.variables;$('#methodologyDerivation').textContent=item.derivation;$('#methodologyExample').textContent=item.example;const chartBox=$('#methodologyChartBox');if(methodologyChart){methodologyChart.destroy();methodologyChart=null}if(item.chart&&window.Chart){chartBox.hidden=false;methodologyChart=createMethodologyChart(item)}else chartBox.hidden=true;$('#methodologyModal').hidden=false;document.body.classList.add('modal-open')}
function createMethodologyChart(item){const c=chartTheme(),canvas=$('#methodologyChart'),common={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{color:c.text}}},scales:{x:{ticks:{color:c.text},grid:{color:c.grid}},y:{ticks:{color:c.text},grid:{color:c.grid}}}};if(item.chart==='bep'){const tr=[],tc=[];for(let x=0;x<=300;x+=25){tr.push({x,y:1200*x});tc.push({x,y:85000+650*x})}return new Chart(canvas,{type:'line',data:{datasets:[{label:'TR — выручка',data:tr,borderColor:'#2457d6',tension:0},{label:'TC — затраты',data:tc,borderColor:'#e25b69',tension:0}]},options:{...common,scales:{...common.scales,x:{...common.scales.x,type:'linear',title:{display:true,text:'Объем, шт.',color:c.text}},y:{...common.scales.y,title:{display:true,text:'Рубли',color:c.text}}}}})}if(item.chart==='depreciation'){return new Chart(canvas,{type:'line',data:{labels:['0 год','1 год','2 год','3 год','4 год','5 год'],datasets:[{label:'Остаточная стоимость, ₽',data:[1200000,984000,768000,552000,336000,120000],borderColor:'#16845d',backgroundColor:'#16845d33',fill:true}]},options:common})}if(item.chart==='annuity'){return new Chart(canvas,{type:'bar',data:{labels:['1','6','12','18','24'],datasets:[{label:'Основной долг',data:[17462,18412,19834,21800,24962],backgroundColor:'#2457d6'},{label:'Проценты',data:[7500,6550,5128,3162,0],backgroundColor:'#e25b69'}]},options:common})}if(item.chart==='cutting'){const points=[];for(let d=20;d<=160;d+=20)points.push({x:d,y:100000/(Math.PI*d)});return new Chart(canvas,{type:'line',data:{datasets:[{label:'n при v = 100 м/мин',data:points,borderColor:'#00a99d',tension:.25}]},options:{...common,scales:{...common.scales,x:{...common.scales.x,type:'linear',title:{display:true,text:'Диаметр D, мм',color:c.text}},y:{...common.scales.y,title:{display:true,text:'Обороты n, об/мин',color:c.text}}}}})}}
function closeMethodologyModal(){if(methodologyChart){methodologyChart.destroy();methodologyChart=null}$('#methodologyModal').hidden=true;document.body.classList.remove('modal-open')}
function initMethodology(){if(!$('#methodologyGrid'))return;renderMethodology();$('#methodologySearch').oninput=renderMethodology;$$('.method-filter-btn').forEach(button=>button.onclick=()=>{methodologyCategory=button.dataset.category;$$('.method-filter-btn').forEach(item=>item.classList.toggle('active',item===button));renderMethodology()});$('#closeMethodologyBtn').onclick=closeMethodologyModal;$('#methodologyModal').onclick=event=>{if(event.target.id==='methodologyModal')closeMethodologyModal()};document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#methodologyModal').hidden)closeMethodologyModal()})}
function n(id){return Math.max(0,Number($(id).value)||0)}
function chartTheme(){const s=getComputedStyle(document.body);return{grid:s.getPropertyValue('--chart-grid').trim(),text:s.getPropertyValue('--chart-text').trim()}}
function syncChartTheme(){const c=chartTheme();if(chart){chart.options.scales.x.ticks.color=c.text;chart.options.scales.y.ticks.color=c.text;chart.options.scales.x.title.color=c.text;chart.options.scales.y.title.color=c.text;chart.options.scales.x.grid.color=c.grid;chart.options.scales.y.grid.color=c.grid;chart.options.plugins.legend.labels.color=c.text;chart.update('none')}if(methodologyChart){methodologyChart.options.plugins.legend.labels.color=c.text;Object.values(methodologyChart.options.scales||{}).forEach(axis=>{axis.ticks.color=c.text;axis.grid.color=c.grid;if(axis.title)axis.title.color=c.text});methodologyChart.update('none')}}
function calcEconomy(){const price=n('#cvpPrice'),variable=n('#cvpVariable'),fixed=n('#cvpFixed'),quantity=n('#cvpQuantity'),margin=price-variable,validMargin=margin>0,bepUnits=validMargin?fixed/margin:0,revenue=price*quantity,profit=margin*quantity-fixed,safety=quantity?((quantity-bepUnits)/quantity*100):0;animateMetric($('#mRevenue'),revenue,money);animateMetric($('#mProfit'),profit,money);animateMetric($('#mBep'),validMargin?Math.ceil(bepUnits):0,v=>validMargin?`${Math.round(v)} шт.`:'—');animateMetric($('#mSafety'),validMargin?safety:0,v=>validMargin?`${v.toFixed(1)}%`:'—');$('#cvpMessage').textContent=validMargin?(profit>=0?`Прибыль: ${money(profit)}`:`Зона убытка: ${money(Math.abs(profit))}`):'Маржинальный доход должен быть больше нуля';$('#cvpMessage').className='hint '+(profit<0||!validMargin?'bad':'');if(window.Chart){const maxQ=Math.max(10,Math.ceil(Math.max(quantity,validMargin?bepUnits:0)*1.35)),tr=[{x:0,y:0},{x:maxQ,y:price*maxQ}],tc=[{x:0,y:fixed},{x:maxQ,y:fixed+variable*maxQ}],bep=validMargin?[{x:bepUnits,y:price*bepUnits}]:[];if(chart){chart.data.datasets[0].data=tr;chart.data.datasets[1].data=tc;chart.data.datasets[2].data=bep;chart.options.scales.x.max=maxQ;chart.update();syncChartTheme();return}const c=chartTheme();chart=new Chart($('#cvpChart'),{type:'line',data:{datasets:[{label:'TR — выручка',data:tr,borderColor:'#2457d6',tension:0},{label:'TC — затраты',data:tc,borderColor:'#e25b69',tension:0},{label:'Точка безубыточности',type:'scatter',data:bep,backgroundColor:'#00a99d',borderColor:'#fff',pointRadius:7,pointBorderWidth:2}]},options:{animation:{duration:600,easing:'easeOutQuart'},responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{color:c.text}}},scales:{x:{type:'linear',min:0,max:maxQ,title:{display:true,text:'Количество, шт.',color:c.text},ticks:{color:c.text},grid:{color:c.grid}},y:{title:{display:true,text:'Рубли',color:c.text},ticks:{color:c.text},grid:{color:c.grid}}}}})}}
function money(v){return Number.isFinite(v)?Math.round(v).toLocaleString('ru-RU')+' ₽':'—'}
function calcTaxes(){const income=n('#napdIncome'),ind=n('#napdIndividuals'),companies=n('#napdCompanies'),emp=n('#napdEmployees'),napd=$('#napdResult');const shareTotal=ind+companies;let napdTax=0;if(emp>0){napd.innerHTML='НПД заблокирован: наличие сотрудников по 422-ФЗ';napd.className='result bad'}else if(income>2400000){napd.innerHTML='НПД заблокирован: лимит 2,4 млн ₽ превышен';napd.className='result bad'}else if(shareTotal<=0){napd.innerHTML='Укажите распределение дохода между физлицами и организациями';napd.className='result bad'}else{napdTax=ind*.04+companies*.06;napd.innerHTML=`Налог: <b>${money(napdTax)}</b> · эффективная ставка ${(napdTax/income*100).toFixed(2)}%`;napd.className='result'}const ui=n('#usnIncome'),ins=n('#usnInsurance'),ue=n('#usnEmployees'),gross=ui*.06,limit=ue>0?gross*.5:gross,deduction=Math.min(ins,limit),usn=Math.max(0,gross-deduction);$('#usnResult').innerHTML=`Налог: <b>${money(usn)}</b><br><small>Вычет ${money(deduction)} (лимит 50% при сотрудниках)</small>`;const u15=n('#usn15Income'),ex=n('#usn15Expenses'),minRate=n('#usn15Min')/100,base=Math.max(0,u15-ex),regular=base*.15,minTax=u15*minRate,usn15=Math.max(regular,minTax);$('#usn15Result').innerHTML=`Налог: <b>${money(usn15)}</b><br><small>${regular<minTax?'Применён минимальный налог':'Доходы минус расходы'}</small>`;$('#taxCompare').innerHTML=`<b>Сравнение:</b> НПД ${money(napdTax||0)} · УСН 6% ${money(usn)} · УСН 15% ${money(usn15)}`;const amount=n('#loanAmount'),rate=n('#loanRate')/1200,term=n('#loanTerm'),pay=rate?amount*rate/(1-Math.pow(1+rate,-term)):amount/Math.max(term,1),leaseCost=n('#leaseCost'),advance=leaseCost*n('#leaseAdvance')/100,leaseBase=leaseCost-advance,leaseTotal=leaseBase*(1+n('#leaseRate')/100),leasePay=leaseTotal/Math.max(n('#leaseTerm'),1);$('#loanResult').innerHTML=`Платёж: <b>${money(pay)}</b>/мес.<br><small>Переплата: ${money(pay*term-amount)}</small>`;$('#leaseResult').innerHTML=`Аванс: <b>${money(advance)}</b><br>Платёж: <b>${money(leasePay)}</b>/мес.<br><small>Итого выплат: ${money(advance+leaseTotal)}</small>`;$('#financeCompare').innerHTML=`<b>Сравнение финансирования:</b> кредит всего ${money(pay*term)} · лизинг всего ${money(advance+leaseTotal)}`}function calcEngineering(){const rho=n('#metal'),l=n('#metalLength')/1000,w=n('#metalWidth')/1000,h=n('#metalHeight')/1000;let v=$('#metalShape').value==='cylinder'?Math.PI*Math.pow(w/2,2)*l:l*w*h;$('#metalResult').textContent=`${(rho*v).toFixed(3)} кг`;const p=n('#volt')*n('#amp')*n('#cos')*(n('#phases')===3?Math.sqrt(3):1)/1000;$('#powerResult').textContent=`${p.toFixed(3)} кВт`}
function calcDepreciation(){const initial=n('#deprInitial'),residual=Math.min(n('#deprResidual'),initial),life=n('#deprLife'),base=Math.max(0,initial-residual),annual=life?base/life:0,monthly=annual/12,rate=life?100/life:0,afterYear=Math.max(residual,initial-annual);$('#deprResult').innerHTML=`Норма: <b>${rate.toFixed(2)}%</b> в год<br>Амортизация за год: <b>${money(annual)}</b><br>За месяц: <b>${money(monthly)}</b><br>Остаточная стоимость через 1 год: <b>${money(afterYear)}</b>`}
function calcCutting(){const diameter=n('#cuttingDiameter'),speed=n('#spindleSpeed'),value=Math.PI*diameter*speed/1000;let advice='Низкая скорость';if(value>=80&&value<=250)advice='Нормальная скорость для стали / чугуна';else if(value>250)advice='Высокая скорость';$('#cuttingResult').textContent=`${value.toFixed(1)} м/мин`;$('#cuttingAdvice').textContent=advice}
function calendarStamp(date,time){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}${m}${d}T${time.replace(':','')}00`}
function calendarUtcStamp(date){const y=date.getUTCFullYear(),m=String(date.getUTCMonth()+1).padStart(2,'0'),d=String(date.getUTCDate()).padStart(2,'0'),h=String(date.getUTCHours()).padStart(2,'0'),min=String(date.getUTCMinutes()).padStart(2,'0'),s=String(date.getUTCSeconds()).padStart(2,'0');return `${y}${m}${d}T${h}${min}${s}Z`}
function icsText(value){return String(value||'').replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n')}
function exportScheduleCalendar(){const group=$('#groupSelect').value,dayIndex=selectedDay,now=new Date(),monday=new Date(now);monday.setHours(0,0,0,0);const offset=monday.getDay()===0?-6:1-monday.getDay();monday.setDate(monday.getDate()+offset);const date=new Date(monday);date.setDate(monday.getDate()+dayIndex);const lessons=(schedule[group]&&schedule[group][days[dayIndex]])||[],events=lessons.map((lesson,index)=>{if(!lesson[0]||lesson[0]==='—')return '';const period=periods[index%periods.length];return `BEGIN:VEVENT\r\nUID:upk-${date.getTime()}-${index}@upk-portal\r\nDTSTAMP:${calendarUtcStamp(new Date())}\r\nDTSTART;TZID=Europe/Moscow:${calendarStamp(date,period.start)}\r\nDTEND;TZID=Europe/Moscow:${calendarStamp(date,period.end)}\r\nSUMMARY:${icsText(lesson[0])}\r\nDESCRIPTION:${icsText(`Преподаватель: ${lesson[1]}`)}\r\nLOCATION:${icsText(lesson[2])}\r\nEND:VEVENT`}).filter(Boolean).join('\r\n');const content=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//UPK Portal//Schedule//RU\r\nCALSCALE:GREGORIAN\r\nX-WR-TIMEZONE:Europe/Moscow\r\nX-WR-CALNAME:${icsText(`Расписание ${group}`)}\r\n${events}\r\nEND:VCALENDAR\r\n`;const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'}));link.download='upk-schedule.ics';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function summary(){const profile=$('#profileSelect').value,price=n('#cvpPrice'),variable=n('#cvpVariable'),fixed=n('#cvpFixed'),quantity=n('#cvpQuantity'),margin=price-variable,bep=margin>0?fixed/margin:0,revenue=price*quantity,profit=margin*quantity-fixed,safety=quantity&&margin>0?(quantity-bep)/quantity*100:0,common=[['Группа',$('#groupSelect').value]],finance=[['Цена за единицу',money(price)],['Переменные затраты',money(variable)],['Постоянные затраты',money(fixed)],['Плановый объём',quantity+' шт.'],['Выручка',money(revenue)],['Прибыль / убыток',money(profit)],['Точка безубыточности',margin>0?Math.ceil(bep)+' шт.':'—'],['Запас финансовой прочности',margin>0?safety.toFixed(1)+'%':'—'],['Рекомендация по налогам',$('#taxCompare').textContent||'—'],['Нормативная база','422-ФЗ; п. 3.1 ст. 346.21 НК РФ'],['Кредит / лизинг',$('#financeCompare').textContent||'—'],['Амортизация ОС',$('#deprResult').textContent||'—']],tech=[['Материал',$('#metal').selectedOptions[0].text],['Форма заготовки',$('#metalShape').selectedOptions[0].text],['Длина / ширина / высота',`${$('#metalLength').value} / ${$('#metalWidth').value} / ${$('#metalHeight').value} мм`],['Плотность',`${$('#metal').value} кг/м³`],['Масса',$('#metalResult').textContent],['Напряжение / ток',`${$('#volt').value} В / ${$('#amp').value} А`],['cos φ',$('#cos').value],['Фазы',$('#phases').value],['Потребляемая мощность',$('#powerResult').textContent]];const block=(title,rows)=>`<div class="summary-block"><h2>${title}</h2>${rows.map(r=>`<div class="summary-row"><span>${r[0]}</span><span>${r[1]||'—'}</span></div>`).join('')}</div>`;let html='<div class="print-title"><b>УПК</b><span>'+({economy:'Финансово-экономический паспорт проекта',technical:'Ведомость технологических расчётов',admin:'Сводный отчёт по модулям'}[profile])+'</span><span>'+new Date().toLocaleDateString('ru-RU')+'</span></div>'+block('Общие параметры',common);if(profile==='economy')html+=block('Финансово-экономический паспорт проекта',finance);else if(profile==='technical')html+=block('Ведомость технологических расчётов',tech);else html+=block('Финансово-экономический блок',finance)+block('Технический блок',tech);$('#summaryContent').innerHTML=html+'<p class="muted">Аналитическое резюме: '+(profile==='technical'?'расчётные параметры заготовки и электросети подготовлены для технологического анализа.':'финансовые показатели и режим налогообложения сопоставлены для принятия управленческого решения.')+'</p><div class="signatures">Выполнил студент группы: ____________________<br><br>Проверил преподаватель: ____________________</div>';}
