function applyProfile(profile){$$('.nav-item[data-profile]').forEach(b=>b.hidden=profile!=='admin'&&b.dataset.profile!==profile);const select=$('#groupSelect'),options=[...select.options];options.forEach(o=>o.hidden=profile!=='admin'&&o.dataset.profile!==profile);const available=options.find(o=>!o.hidden);if(select.selectedOptions[0]&&select.selectedOptions[0].hidden&&available)select.value=available.value;renderSchedule();summary();if($('#editorGroup'))editorRows()}
function csvData(){const profile=$('#profileSelect').value,rows=[['Раздел','Показатель','Значение'],['Параметры','Профиль',$('#profileSelect').selectedOptions[0].text],['Параметры','Группа',$('#groupSelect').value]];if(profile!=='technical')rows.push(['Финансы','Выручка',$('#mRevenue').textContent],['Финансы','Прибыль / убыток',$('#mProfit').textContent],['Финансы','Точка безубыточности',$('#mBep').textContent],['Финансы','Запас финансовой прочности',$('#mSafety').textContent],['Финансы','Налоговая рекомендация',$('#taxCompare').textContent],['Финансы','Кредит / лизинг',$('#financeCompare').textContent]);if(profile!=='economy')rows.push(['Технология','Материал',$('#metal').selectedOptions[0].text],['Технология','Плотность',$('#metal').value+' кг/м³'],['Технология','Масса',$('#metalResult').textContent],['Технология','Напряжение / ток',$('#volt').value+' В / '+$('#amp').value+' А'],['Технология','Мощность',$('#powerResult').textContent]);return '﻿'+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\r\n')}
function downloadCsv(){const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csvData());a.download='upk-summary.csv';a.click()}
function copySummary(){const text=$('#summaryContent').innerText;const done=()=>{const b=$('#copyBtn');b.textContent='Скопировано';setTimeout(()=>b.textContent='Копировать для Word',1200)};if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(text).then(done).catch(()=>{fallbackCopy(text);done()});else{fallbackCopy(text);done()}}
function fallbackCopy(text){const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}
function openQr(){const url=location.href;$('#qrLink').textContent=url;$('#qrCode').innerHTML='';if(window.QRCode)new QRCode($('#qrCode'),{text:url,width:220,height:220,colorDark:'#111827',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});else $('#qrCode').textContent='QR-библиотека ещё загружается. Повторите открытие окна.';$('#qrModal').hidden=false}
function closeQr(){$('#qrModal').hidden=true}
function importSchedule(){const raw=$('#scheduleImport').value.trim();if(!raw)return;try{const text=raw.replace(/^\s*const\s+(?:schedule|baseSchedule)\s*=\s*/,'').replace(/;\s*$/,'');const imported=JSON.parse(text);if(!imported||typeof imported!=='object')throw new Error('Неверный объект');schedule=JSON.parse(JSON.stringify(baseSchedule));Object.entries(imported).forEach(([group,groupDays])=>{schedule[group]||(schedule[group]={});Object.entries(groupDays||{}).forEach(([day,lessons])=>{if(days.includes(day))schedule[group][day]=cleanLessons(lessons)});});saveCustomSchedule();refreshGroupOptions();renderSchedule();editorRows();$('#editorStatus').textContent='Расписание импортировано и сохранено на этом компьютере.'}catch(error){$('#editorStatus').textContent='Не удалось импортировать: вставьте JSON или корректный экспортированный код.'}}
function registerServiceWorker(){if(!('serviceWorker' in navigator)||location.protocol==='file:')return;let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;window.location.reload()}});window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(registration=>{const update=()=>registration.update().catch(error=>console.error('Не удалось проверить обновление Service Worker:',error));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')update()});setInterval(update,5*60*1000);update()}).catch(error=>console.error('Не удалось зарегистрировать Service Worker:',error))})}
function syncTitleGroup(){const select=$('#titleGroup');if(!select)return;select.innerHTML=[...$('#groupSelect').options].map(o=>`<option value="${escapeHtml(o.value)}">${escapeHtml(o.textContent)}</option>`).join('');select.value=$('#groupSelect').value}
function printTitle(){const type=$('#titleType').value,subject=$('#titleSubject').value||'________________',topic=$('#titleTopic').value||'________________',teacher=$('#titleTeacher').value||'________________',student=$('#titleStudent').value.trim(),group=$('#titleGroup').value,year=new Date().getFullYear(),studentLine=student?escapeHtml(student):'____________________________';const win=window.open('','_blank','width=900,height=700');if(!win){alert('Разрешите всплывающие окна для печати титульного листа.');return}win.document.write(`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Титульный лист</title><style>@page{size:A4;margin:20mm}body{font-family:"Times New Roman",serif;font-size:14pt;color:#000}.center{text-align:center}.topic{margin-top:55mm;text-align:center;font-size:16pt;font-weight:bold}.details{margin-top:35mm;margin-left:52%;line-height:1.7}.footer{position:fixed;bottom:12mm;left:0;right:0;text-align:center}</style></head><body><div class="center">МИНИСТЕРСТВО ОБРАЗОВАНИЯ ТУЛЬСКОЙ ОБЛАСТИ<br>ГПОУ ТО «УЗЛОВСКИЙ ПОЛИТЕХНИЧЕСКИЙ КОЛЛЕДЖ»</div><div class="topic">${escapeHtml(type)}<br>по дисциплине «${escapeHtml(subject)}»<br>на тему: «${escapeHtml(topic)}»</div><div class="details">Выполнил студент группы ${escapeHtml(group)}<br>${studentLine}<br><br>Проверил преподаватель<br>${escapeHtml(teacher)}<br>____________________________</div><div class="footer">Узловая<br>${year}</div><script>window.onload=()=>{window.print();window.onafterprint=()=>window.close()}<\/script></body></html>`);win.document.close()}
function calcGrades(){const excellent=Math.max(0,n('#gradeExcellent')),good=Math.max(0,n('#gradeGood')),satisfactory=Math.max(0,n('#gradeSatisfactory')),total=excellent+good+satisfactory,gpa=total?(excellent*5+good*4+satisfactory*3)/total:0,share=total?excellent/total*100:0;let verdict='Введите количество оценок.';if(total&&satisfactory>0)verdict='Обычный диплом (есть удовлетворительные оценки)';else if(total&&share>=75)verdict='Претендует на диплом с отличием (красный диплом) ★';else if(total){const needed=Math.max(0,Math.ceil((.75*total-excellent)/.25));verdict=`Для красного диплома не хватает ${needed} пятёрок`};$('#gradeResult').innerHTML=`Средний балл: <b>${gpa.toFixed(2)}</b><br>Доля пятёрок: <b>${share.toFixed(1)}%</b><br><span>${verdict}</span>`}
function loadDeadlines(){let list=[];try{list=JSON.parse(localStorage.getItem('upk_deadlines')||'[]')}catch(_){list=[]}const today=new Date();today.setHours(0,0,0,0);$('#deadlineList').innerHTML=list.sort((a,b)=>a.date.localeCompare(b.date)).map(item=>{const date=new Date(`${item.date}T00:00:00`),diff=Math.round((date-today)/86400000),label=diff<0?'Срок прошел':diff===0?'Сегодня сдача':`Осталось ${diff} дн.`,subject=item.subject?`<span class="deadline-subject">${escapeHtml(item.subject)}</span>`:'';return `<div class="deadline-item ${item.done?'done':''}"><div><strong>${escapeHtml(item.title)}</strong><small>${date.toLocaleDateString('ru-RU')}</small>${subject}</div><span class="deadline-badge ${diff<0?'overdue':''}">${label}</span><div class="deadline-actions"><button class="secondary deadline-toggle" data-id="${item.id}" type="button">${item.done?'Вернуть':'Готово'}</button><button class="secondary deadline-delete" data-id="${item.id}" type="button">Удалить</button></div></div>`}).join('')||'<p class="muted">Дедлайнов пока нет.</p>';$$('.deadline-toggle').forEach(b=>b.onclick=()=>updateDeadline(b.dataset.id));$$('.deadline-delete').forEach(b=>b.onclick=()=>deleteDeadline(b.dataset.id))}
function saveDeadlines(list){localStorage.setItem('upk_deadlines',JSON.stringify(list));loadDeadlines()}
function updateDeadline(id){const list=JSON.parse(localStorage.getItem('upk_deadlines')||'[]');const item=list.find(x=>x.id===id);if(item)item.done=!item.done;saveDeadlines(list)}
function deleteDeadline(id){saveDeadlines(JSON.parse(localStorage.getItem('upk_deadlines')||'[]').filter(x=>x.id!==id))}
function clearCompletedDeadlines(){saveDeadlines(JSON.parse(localStorage.getItem('upk_deadlines')||'[]').filter(item=>!item.done))}
function addDeadline(){const title=$('#deadlineTitle').value.trim(),subject=$('#deadlineSubject').value.trim(),date=$('#deadlineDate').value;if(!title||!date)return;const list=JSON.parse(localStorage.getItem('upk_deadlines')||'[]');list.push({id:Date.now().toString(),title,subject,date,done:false});saveDeadlines(list);$('#deadlineTitle').value='';$('#deadlineSubject').value='';$('#deadlineDate').value=''}
function initInstallPrompt(){window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredPrompt=event;$('#installPwaBtn').hidden=false});window.addEventListener('appinstalled',()=>{deferredPrompt=null;$('#installPwaBtn').hidden=true});$('#installPwaBtn').onclick=async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#installPwaBtn').hidden=true}}
function closeSidebar(){ $('#sidebar').classList.remove('open');$('#sidebarOverlay').classList.remove('visible'); }
